# The training ground (sector PT1; plan_training.py lays each operation's cones on it). All of it stands on one
# plane rising 1.2 % to the east (the slope a real driving pad is given to drain; the hillside itself rises 2.2 %):
# street-surface height pt_z(x). The asphalt pad, the fence round the compound (6 m outside the pad, 50 m to the
# north: the service yard), the gate where the access street arrives (network_edits, "Campaign").
PT_ROAD_X = 2879.37
PT_PAD = (2776.0, 3026.0, -2027.0, -1755.0)              # west, east, south, north
PT_FENCE = (2770.0, 3032.0, -2033.0, -1705.0)
PT_GATE_HALF = 6.3                                       # half the gate's opening: the street's carriageway and kerbs
PT_PARKING = (PT_ROAD_X + 3.0, 2990.0, -1738.0, -1721.0)  # the car park east of the drive, joined to it


def pt_z(x):
    return round(9.9 + 0.012 * (x - 2901.0), 3)


# level lines east-west across the compound, every 15.6 m: the plane only slopes along them, so between them the
# ground is the same plane exactly
PT_LEVELS = [[(PT_FENCE[0], round(PT_FENCE[2] + 15.619 * k, 2), pt_z(PT_FENCE[0])),
              (PT_FENCE[1], round(PT_FENCE[2] + 15.619 * k, 2), pt_z(PT_FENCE[1]))] for k in range(22)]
