# The access street crosses the seam between EP5 and PT1 (y = -1300). A sector's ground is a blend of every line near
# it, and each of the two has its own relief samples on its own side only: at the seam the two blends differed by 7 cm
# at the kerbs (a step across both sidewalks). So both hold these two lines too, along the backs of the street's
# sidewalks either side of the seam, at the street's own height: near the street the same lines now decide in both.
PT_SEAM = [[(PT_ROAD_X + side * 9.8, y, z) for y, z in ((-1290.23, 15.96), (-1298.12, 15.81), (-1306.01, 15.68),
                                                         (-1313.90, 15.56), (-1321.78, 15.44), (-1329.67, 15.34))]
           for side in (-1.0, 1.0)]


def _pt_paint():
    w, e, s, n = PT_PAD
    out = [{"colour": "white", "width": 0.15, "line": [(w + 0.6, s + 0.6), (e - 0.6, s + 0.6), (e - 0.6, n - 0.6),
                                                        (w + 0.6, n - 0.6), (w + 0.6, s + 0.6)]}]
    # reference crosses on a 50 m grid: what the instructors set the cones out from
    for i in range(5):
        for j in range(6):
            x, y = w + 25.0 + 50.0 * i, s + 11.0 + 50.0 * j
            out.append({"colour": "white", "width": 0.10, "line": [(x - 0.6, y), (x + 0.6, y)]})
            out.append({"colour": "white", "width": 0.10, "line": [(x, y - 0.6), (x, y + 0.6)]})
    # the car park: two rows of bays, 2.5 x 5 m, either side of a 7 m aisle
    pw, pe, ps, pn = PT_PARKING
    x = 2900.0
    while x <= pe + 1e-6:
        out.append({"colour": "white", "width": 0.10, "line": [(x, pn - 0.2), (x, pn - 5.0)]})
        out.append({"colour": "white", "width": 0.10, "line": [(x, ps + 0.2), (x, ps + 5.0)]})
        x += 2.5
    return out


def _pt_pieces():
    w, e, s, n = PT_PAD
    cx, cy = (w + e) / 2.0, (s + n) / 2.0
    mast = "/Game/CityPark/Meshes/SportsGround/SM_TennisFloodlight"       # its lamps look along local -Y
    out = []
    spots = [(w - 3.0, s + 20.0), (w - 3.0, cy), (w - 3.0, n - 20.0), (e + 3.0, s + 20.0), (e + 3.0, cy), (e + 3.0, n - 20.0),
             (w + 60.0, s - 3.0), (cx, s - 3.0), (e - 60.0, s - 3.0), (w + 25.0, n + 4.0), (e - 60.0, n + 4.0)]
    for x, y in spots:
        out.append((mast, (x, y), round(math.degrees(math.atan2(cx - x, cy - y)) % 360.0, 1), 1.0))
    # the instructors' stores by the building: two containers and a mobile light tower; a dumpster and two cabins
    out.append(("/Game/Prop/CONSTRUCTION/Kit_ShippingContainer/Mesh/SM_ShippingContainer_A01_N1", (2796.0, -1716.0), 90.0, 1.0))
    out.append(("/Game/Prop/CONSTRUCTION/Kit_ShippingContainer/Mesh/SM_ShippingContainer_C01_N1", (2796.0, -1721.0), 90.0, 1.0))
    out.append(("/Game/Construction_VOL1/Meshes/SM_LightGenerator_01a", (2868.0, -1750.0), 0.0, 1.0))
    out.append(("/Game/Construction_VOL1/Meshes/SM_Dumpster", (2812.0, -1711.0), 90.0, 1.0))
    out.append(("/Game/Construction_VOL1/Meshes/SM_Portapotty_01", (2780.0, -1712.0), 0.0, 1.0))
    out.append(("/Game/Construction_VOL1/Meshes/SM_Portapotty_01", (2782.0, -1712.0), 0.0, 1.0))
    return out


# The stadium (2026-11-18, for the campaign: operations 10 and 14 are set in the "Setor do Estadio", and operation 14
# ends at the stadium's entrance, the street corner at (2184, 778)). The campaign's own model has, where the drawing
# shows the walled compound north-east of downtown, a ring of stands 198 x 186 m with four towers 60 m high at the
# middle of its sides. Built to that: a bowl with round corners on the compound's own footprint, the pitch's long
# axis east-west, the main stands north and south, a floodlight tower behind the middle of each side.
# stadium_mesh.py builds it (structure EST); sector CC12 lays the ground round it.
#   centre, half, corner   the bowl's outer footprint: a rectangle of twice `half` with corners of that radius
#   inner_half, inner_corner   the front of the stands, round the pitch and its margins
#   pitch   the field of play, metres east-west by north-south
#   z       street-surface height of the level ground the bowl stands on (block ground is a kerb above)
#   gate    the corner the main entrance faces (operation 14's "Entrada do estadio")
STADIUM = {"centre": (2060.6, 667.5), "half": (87.0, 84.0), "corner": 34.0, "inner_half": (60.5, 41.5), "inner_corner": 12.0,
           "pitch": (105.0, 68.0), "z": 4.5, "gate": (2184.0, 778.1)}


def round_rect(centre, half, corner, grow=0.0, steps=10):
    """A rectangle with round corners, let out by `grow` metres all round, counter-clockwise from the middle of its
    east side: (x, y) points, `steps` to a corner."""
    cx, cy = centre
    a, b, r = half[0] + grow, half[1] + grow, corner + grow
    out = []
    for qx, qy, first in ((1, 1, 0.0), (-1, 1, 90.0), (-1, -1, 180.0), (1, -1, 270.0)):
        for k in range(steps + 1):
            t = math.radians(first + 90.0 * k / steps)
            out.append((round(cx + qx * (a - r) + r * math.cos(t), 2), round(cy + qy * (b - r) + r * math.sin(t), 2)))
    return out


def stadium_ring(grow=0.0, steps=10):
    """The stadium's outer footprint let out by `grow` metres."""
    return round_rect(STADIUM["centre"], STADIUM["half"], STADIUM["corner"], grow, steps)


