def place_point(name, a, b):
    """Map coordinates of a point of a place's site (a across the front, b towards the front, from its centre)."""
    p = PLACES[name]
    t = math.radians(p["front"])
    fx, fy = math.cos(t), math.sin(t)
    return (round(p["centre"][0] - fy * a + fx * b, 2), round(p["centre"][1] + fx * a + fy * b, 2))


def place_ring(name, grow=0.0, part=None):
    """A place's site as a rectangle let out by `grow`, counter-clockwise; `part` = (a0, a1, b0, b1) for a piece of
    it in the site's own coordinates."""
    w, d = PLACES[name]["size"]
    a0, a1, b0, b1 = part or (-w / 2.0, w / 2.0, -d / 2.0, d / 2.0)
    ring = [place_point(name, a, b) for a, b in ((a0 - grow, b0 - grow), (a1 + grow, b0 - grow), (a1 + grow, b1 + grow), (a0 - grow, b1 + grow))]
    area = sum(ring[k][0] * ring[(k + 1) % 4][1] - ring[(k + 1) % 4][0] * ring[k][1] for k in range(4))
    return ring if area > 0 else ring[::-1]


def solid_rings(sector):
    """Ground of the sector where a building of its own stands (a campaign place, the stadium): nothing is planted
    or furnished there (plan_props.py), whatever the ground is."""
    out = [place_ring(name, 1.0) for name, p in PLACES.items() if p["sector"] == sector]
    if sector == "CC12":
        out.append(stadium_ring(1.0))
    return out


def _closed(ring):
    return list(ring) + [ring[0]]


def _pad(name, grow=1.0):
    """A level pad over a place's whole site: its edge alone, held at the place's height. (Lines across it too were
    tried first: every held line pulls the ground of the whole neighbourhood as a street does, and nine of them
    moved the floors of 33 houses round the power plant by up to 2.6 m. The edge keeps the inside level by itself.)"""
    return {"z": PLACES[name]["z"], "lines": [_closed(place_ring(name, grow))]}


def _add(sector, key, items):
    SECTORS[sector][key] = list(SECTORS[sector].get(key, [])) + list(items)


def _circle(centre, radius, steps=32):
    return [(round(centre[0] + radius * math.cos(2.0 * math.pi * k / steps), 2), round(centre[1] + radius * math.sin(2.0 * math.pi * k / steps), 2))
            for k in range(steps + 1)]


def _helipad(name, a, b, radius=8.0):
    """Paint of a helicopter pad on an apron: a white circle and an H."""
    c = place_point(name, a, b)
    out = [{"colour": "white", "line": _circle(c, radius), "width": 0.45}]
    for da in (-2.2, 2.2):
        out.append({"colour": "white", "line": [place_point(name, a + da, b - 3.2), place_point(name, a + da, b + 3.2)], "width": 0.7})
    out.append({"colour": "white", "line": [place_point(name, a - 2.2, b), place_point(name, a + 2.2, b)], "width": 0.7})
    return out


# no building of the sector's own plan on a place's site (3 m round it)
for _name, _p in PLACES.items():
    _add(_p["sector"], "open", [place_ring(_name, 3.0)])
