# ---- paths in the parks (2026-11-19) -----------------------------------------------------------------------------
# The three parks of the centre were woods on a lawn with no way through: the waterfront park (CS12), the esplanade
# (CC5), the knoll (CC11). Each gets gravel paths ("paths", sector_mesh.py) and benches beside them, facing them.
def _wave(a, b, swing, waves, step=8.0):
    """Points from a to b that swing `swing` metres to either side, `waves` full swings, none at the two ends."""
    (ax, ay), (bx, by) = a, b
    d = math.hypot(bx - ax, by - ay)
    nx, ny = -(by - ay) / d, (bx - ax) / d
    count = max(2, int(round(d / step)))
    out = []
    for k in range(count + 1):
        t = k / count
        off = swing * math.sin(2.0 * math.pi * waves * t) * math.sin(math.pi * t) ** 0.5
        out.append((round(ax + (bx - ax) * t + nx * off, 2), round(ay + (by - ay) * t + ny * off, 2)))
    return out


def _park_paths(sector, lines, width=3.0, bench_every=42.0):
    """Paths along the lines, and a row of benches beside each (0.9 m beyond its left edge, looking at it)."""
    _add(sector, "paths", [{"line": line, "width": width} for line in lines])
    rows = []
    for line in lines:
        row = []
        for k, (x, y) in enumerate(line):
            ax, ay = line[max(k - 1, 0)]
            bx, by = line[min(k + 1, len(line) - 1)]
            d = math.hypot(bx - ax, by - ay) or 1.0
            row.append((round(x - (by - ay) / d * (width / 2.0 + 0.9), 2), round(y + (bx - ax) / d * (width / 2.0 + 0.9), 2)))
        rows.append({"line": row, "every": bench_every, "side": "right"})
    _add(sector, "benches", rows)


