# ---- the other half of a street (2026-11-18) ---------------------------------------------------------------------
# Along the city's edge the block inside holds its half of the perimeter street, up to the centre line, and a strip
# (ED1..ED29) holds the other half with a verge. Thirteen stretches had no strip: a gap between two strips, the outer
# half of a bend, a slit beside a strip's end. There the landscape, painted as asphalt, was the other half of the
# street: no kerb, no sidewalk, no markings, and beside EP5 a drop to the river bank (audit_geometry.py lists them as
# "half" and, the outer halves of five bends, as "no ground"). Each is a small sector of its own. Its outline runs
# through the neighbours' own points. Where it shares a side with a neighbour away from the street, a seam "like"
# that neighbour gives both the same points and heights; such a seam starts EDGE_SEAM_START_M beyond the street's
# centre line, where the height is the street's own for everyone, so the block inside the street is not touched.
EDGE_SEAM_START_M = 8.0
_EDGE_SEAMS = []


def _edge_fill(name, beside, ring, shared=(), walls=None):
    """Adds the sector `name`: the missing half of a street beside sector `beside`, a verge of lawn round it.
    ring: its outline, the side along the street first. shared: (neighbour, [points]) for each side it shares with a
    neighbour away from the street; "+" before the neighbour's name: the first point lies on the street's centre
    line, and the seam starts EDGE_SEAM_START_M further on. walls: sides that hold the ground back (see "walls")."""
    ring = [(float(x), float(y)) for x, y in ring]
    eye, look = ring[0], ring[1]
    turn = sum(ring[i][0] * ring[(i + 1) % len(ring)][1] - ring[(i + 1) % len(ring)][0] * ring[i][1] for i in range(len(ring)))
    if turn < 0.0:
        ring = ring[::-1]                       # counter-clockwise, as every outline
    xs, ys = [q[0] for q in ring], [q[1] for q in ring]
    around = [(min(xs) - 5.0, min(ys) - 5.0), (max(xs) + 5.0, min(ys) - 5.0), (max(xs) + 5.0, max(ys) + 5.0), (min(xs) - 5.0, max(ys) + 5.0)]
    spec = {"outline": ring, "district": "port", "title": "Borda da cidade - a outra metade da rua junto do %s" % beside,
            "status": "built", "max_height_m": 30.0,
            "open": [around], "wild": [around],         # (no "relief": the verge lies at the street's height, as ED1..ED29's)
            "park_tree_m2": 400.0, "park_bench_m": 1000000000.0,
            "views": [("edge_a", eye, look), ("edge_b", look, eye)]}
    if walls:
        spec["walls"] = walls
    SECTORS[name] = spec
    for like, line in shared:
        line = [(float(x), float(y)) for x, y in line]
        if like.startswith("+"):
            like = like[1:]
            (ax, ay), (bx, by) = line[0], line[1]
            t = EDGE_SEAM_START_M / math.hypot(bx - ax, by - ay)
            line[0] = (round(ax + (bx - ax) * t, 2), round(ay + (by - ay) * t, 2))
        _EDGE_SEAMS.append({"line": line, "like": like})


