# ---- seams ---------------------------------------------------------------------------------------------------
# A side of an outline has a height only at its points: with nothing but its two ends it is a straight rail from
# one corner's height to the other's, whatever the ground does in between. Over a hill both sectors' meshes then
# fold down (or up) to the rail along the side, and where the two hold different heights a slit stands open between
# them (the cliff sides of the Falesia Norte dived 30 m; audit_seams.py, 2026-11-18). A seam cures a shared side on
# open ground: every sector whose outline runs along it gets the seam's points (SEAM_STEP_M apart) in its outline
# and the seam's heights in its levels, and lets go of whatever it held along that line before. So neighbours have
# the same points at the same heights without either spec saying so. A sector with a seam point anywhere on its
# outline must be made again when the seam is added or changed (seamed() lists them).
#   "line"  the stretch, a polyline along the shared side(s); it may run along several sectors, one after another
#   "like"  (optional) a sector's name: the seam takes the heights of that sector's own ground as it is without
#           the seam (a built-up sector beside natural ground keeps its ground; the natural side comes to it).
#           Without it the seam takes the natural relief, eased into the streets' height beside a road by the rule
#           of a sector's "relief" (SEAM_CLEAR_M, SEAM_BLEND_M: that rule's defaults).
# Two seams that share a point take the earlier one's height there.
# The seam's lines go into the levels marked "pin": they hold on a carriageway too (roadgeom.HeightField), so two
# sectors that share a seam across a street have the same height there.
SEAM_STEP_M = 8.0
SEAM_CLEAR_M, SEAM_BLEND_M = 12.0, 20.0
SEAM_MERGE_M = 0.25             # a seam point this close to a point of the outline is not put in beside it
